16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Period;
23	import java.util.Map;
24	import java.util.UUID;
25	
26	/**
27	 * Pure derivations of an {@link Owner}'s read-only attributes.
28	 *
29	 * <p>Each method computes one derived value from an owner's own field values and
30	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
31	 * exposes these through thin {@code @Transient} getters that pass in the relevant
32	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
33	 * to describe its persistent state and relationships while its growing family of
34	 * derived attributes lives together in one place.
35	 */
36	final class OwnerDerivations {
37	
38	    /** Fixed city-to-region table used to derive {@link #region}. */
39	    private static final Map<String, String> CITY_REGION = Map.of(
40	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
41	
42	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
43	     *  {@link #region} in preference to the city. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
46	
47	    private OwnerDerivations() {
48	    }
49	
50	    /**
51	     * The owner's locality, i.e. the canonical region it belongs to. This is read
52	     * from the region-and-hash {@code customerCode} identity: the region is the
53	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
54	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
55	     * been assigned a customer code (for example while its create request is still
56	     * being validated) this falls back to the region derived directly from its own
57	     * fields (see {@link #region(String, String)}).
58	     *
59	     * @return the canonical region string, or {@code "UNKNOWN"}
60	     */
61	    static String locality(String customerCode, String postcode, String city) {
62	        if (customerCode != null) {
63	            int dash = customerCode.indexOf('-');
64	            if (dash >= 0) {
65	                return customerCode.substring(0, dash);
66	            }
67	        }
68	        return region(postcode, city);
69	    }
70	
71	    /**
72	     * The canonical region derived for an owner from its own fields. The postcode is
73	     * consulted first: when it is present and falls within a known region's inclusive
74	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
75	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
76	     * known range does this fall back to the fixed city-to-region table
77	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
78	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
79	     * the same region for the known cities while disambiguating cities that share a name
80	     * via their postcode.
81	     *
82	     * @return the canonical region string, or {@code "UNKNOWN"}
83	     */
84	    static String region(String postcode, String city) {
85	        String byPostcode = regionForPostcode(postcode);
86	        if (byPostcode != null) {
87	            return byPostcode;
88	        }
89	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
90	    }
91	
92	    /**
93	     * The region whose inclusive postcode range contains the given postcode, or
94	     * {@code null} when the postcode is absent, not a four-digit number, or in no
95	     * known range.
96	     */
97	    private static String regionForPostcode(String postcode) {
98	        if (postcode == null || !postcode.matches("\\d{4}")) {
99	            return null;
100	        }
101	        int value = Integer.parseInt(postcode);
102	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
103	            int[] range = entry.getValue();
104	            if (value >= range[0] && value <= range[1]) {
105	                return entry.getKey();
106	            }
107	        }
108	        return null;
109	    }
110	
111	    /**
112	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
113	     * absent postcode is always accepted, a present postcode must be exactly four
114	     * digits and, when the region has a known inclusive postcode range
115	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
116	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
117	     * four-digit postcode.
118	     *
119	     * @return {@code true} if the postcode is absent or valid for the region
120	     */
121	    static boolean postcodeMatchesRegion(String postcode, String region) {
122	        if (postcode == null) {
123	            return true;
124	        }
125	        if (!postcode.matches("\\d{4}")) {
126	            return false;
127	        }
128	        int[] range = REGION_POSTCODES.get(region);
129	        if (range == null) {
130	            return true;
131	        }
132	        int value = Integer.parseInt(postcode);
133	        return value >= range[0] && value <= range[1];
134	    }
135	
136	    /**
137	     * The owner's membership level, a number from 1 to 3 assigned at creation:
138	     * starting at 1, add 1 when an {@code email} is present and add 1 when
139	     * {@code namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
140	     *
141	     * @return the membership level, from 1 to 3
142	     */
143	    static int membershipLevel(String email, Integer namesakeCount) {
144	        int level = 1;
145	        if (email != null && !email.isBlank()) {
146	            level++;
147	        }
148	        if (namesakeCount != null && namesakeCount == 0) {
149	            level++;
150	        }
151	        return Math.min(level, 3);
152	    }
153	
154	    /**
155	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
156	     * is present, otherwise {@code "PHONE"}.
157	     *
158	     * @return {@code "EMAIL"} or {@code "PHONE"}
159	     */
160	    static String contactPreference(String email) {
161	        if (email != null && !email.isBlank()) {
162	            return "EMAIL";
163	        }
164	        return "PHONE";
165	    }
166	
167	    /**
168	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
169	     * given {@code customerCode}, processed right-to-left with every second digit
170	     * doubled (and reduced by 9 when the double exceeds 9). Non-digit characters are
171	     * ignored, and an absent or digit-free customer code yields {@code 0}.
172	     *
173	     * @return the Luhn check digit, from 0 to 9
174	     */
175	    static int checkDigit(String customerCode) {
176	        int sum = 0;
177	        boolean doubleDigit = true;
178	        for (int i = (customerCode == null ? 0 : customerCode.length()) - 1; i >= 0; i--) {
179	            char c = customerCode.charAt(i);
180	            if (c < '0' || c > '9') {
181	                continue;
182	            }
183	            int d = c - '0';
184	            if (doubleDigit) {
185	                d *= 2;
186	                if (d > 9) {
187	                    d -= 9;
188	                }
189	            }
190	            sum += d;
191	            doubleDigit = !doubleDigit;
192	        }
193	        return (10 - (sum % 10)) % 10;
194	    }
195	
196	    /**
197	     * The owner's age band, derived from its {@code birthDate} measured against its
198	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
199	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
200	     * over. The age is the number of whole years between the two dates. Returns
201	     * {@code null} when either date is absent, so no band is reported for an owner
202	     * without a supplied birth date.
203	     *
204	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
205	     */
206	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
207	        if (birthDate == null || registrationDate == null) {
208	            return null;
209	        }
210	        int age = Period.between(birthDate, registrationDate).getYears();
211	        if (age < 18) {
212	            return "MINOR";
213	        }
214	        if (age < 65) {
215	            return "ADULT";
216	        }
217	        return "SENIOR";
218	    }
219	
220	    /**
221	     * The single derived key used for duplicate detection, formed as
222	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
223	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
224	     * is the stored (lower-cased) email or the empty string when absent, and the
225	     * household component is the stored {@code householdId} or the empty string
226	     * when the owner belongs to no household.
227	     *
228	     * @return the owner's identity key
229	     */
230	    static String identityKey(String telephone, String email, String householdId) {
231	        String tel = telephone == null ? "" : telephone;
232	        String mail = email == null ? "" : email;
233	        String household = householdId == null ? "" : householdId;
234	        return tel + "|" + mail + "|" + household;
235	    }
236	
237	    /**
238	     * The owner's customer code, formatted {@code <REGION>-<HASH8>}: {@code region} is
239	     * the owner's canonical region (see {@link #region(String, String)}) and HASH8 is the
240	     * first eight upper-case hexadecimal characters of the SHA-256 digest of the owner's
241	     * normalised telephone concatenated with its last name (e.g. {@code NSW-9F86D081}).
242	     *
243	     * @return the customer code
244	     */
245	    static String customerCode(String region, String telephone, String lastName) {
246	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
247	        return String.format("%s-%s", region, hash8);
248	    }
249	
250	    /**
251	     * The stable identifier for the household described by the given
252	     * {@link Owner#householdKey() household key}, derived deterministically so every
253	     * owner in a household resolves to the same value.
254	     *
255	     * @return the household identifier
256	     */
257	    static String householdId(String householdKey) {
258	        return UUID.nameUUIDFromBytes(householdKey.getBytes(StandardCharsets.UTF_8)).toString();
259	    }
260	
261	    /**
262	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
263	     * hexadecimal string. Callers take the prefix and case they need.
264	     */
265	    static String sha256Hex(String value) {
266	        try {
267	            byte[] digest = MessageDigest.getInstance("SHA-256")
268	                .digest(value.getBytes(StandardCharsets.UTF_8));
269	            StringBuilder hex = new StringBuilder(digest.length * 2);
270	            for (byte b : digest) {
271	                hex.append(String.format("%02x", b));
272	            }
273	            return hex.toString();
274	        } catch (NoSuchAlgorithmException e) {
275	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
276	        }
277	    }
278	}
