54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        if (!normalizeNewOwner(owner)) {
112	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
113	        }
114	        if (dailyLimitReached(owner.getRegistrationDate())) {
115	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
116	        }
117	        if (cityIsAtCapacity(owner.getCity())) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        Optional<Owner> householdMember = findHouseholdMember(owner);
121	        if (householdMember.isPresent() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
122	            joinHousehold(owner, householdMember.get());
123	        }
124	        if (identityKeyAlreadyUsed(owner)) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        assignDerivedAttributes(owner);
128	        this.clinicService.saveOwner(owner);
129	        auditOwnerCreated(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
139	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
140	        if (currentOwner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        currentOwner.setAddress(ownerFieldsDto.getAddress());
144	        currentOwner.setCity(ownerFieldsDto.getCity());
145	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
146	        currentOwner.setLastName(ownerFieldsDto.getLastName());
147	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
148	        String email = ownerFieldsDto.getEmail();
149	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
150	        this.clinicService.saveOwner(currentOwner);
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Transactional
156	    @Override
157	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        this.clinicService.deleteOwner(owner);
163	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Pet pet = petMapper.toPet(petFieldsDto);
175	        owner.setId(ownerId);
176	        pet.setOwner(owner);
177	        pet.getType().setName(null);
178	        this.clinicService.savePet(pet);
179	        PetDto petDto = petMapper.toPetDto(pet);
180	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
181	            .buildAndExpand(pet.getId()).toUri());
182	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner != null) {
190	            Pet currentPet = this.clinicService.findPetById(petId);
191	            if (currentPet != null) {
192	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
193	                currentPet.setName(petFieldsDto.getName());
194	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
195	                this.clinicService.savePet(currentPet);
196	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	            }
198	        }
199	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
205	        HttpHeaders headers = new HttpHeaders();
206	        Visit visit = visitMapper.toVisit(visitFieldsDto);
207	        Pet pet = new Pet();
208	        pet.setId(petId);
209	        visit.setPet(pet);
210	        this.clinicService.saveVisit(visit);
211	        VisitDto visitDto = visitMapper.toVisitDto(visit);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
213	            .buildAndExpand(visit.getId()).toUri());
214	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
215	    }
216	
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
233	     * the canonical form each stored value must take: the address is trimmed,
234	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
235	     * telephone is converted to E.164, any email is lower-cased and a missing
236	     * registration date defaults to today. Field-level rejections are reported here
237	     * rather than inline in {@link #addOwner}, and normalisation runs before any
238	     * household comparison so those comparisons see the canonical values.
239	     *
240	     * @param owner the freshly-mapped owner to normalise
241	     * @return {@code true} if the fields are valid, or {@code false} if the address
242	     *         is blank after normalisation, the telephone cannot form a valid
243	     *         E.164 number, or a supplied registration date is later than the
244	     *         server date, in which case the request must be rejected with
245	     *         {@code 400 Bad Request}
246	     */
247	    private boolean normalizeNewOwner(Owner owner) {
248	        String address = Owner.normalizeAddress(owner.getAddress());
249	        if (address.isEmpty()) {
250	            return false;
251	        }
252	        owner.setAddress(address);
253	        String telephone = toE164(owner.getTelephone());
254	        if (telephone == null) {
255	            return false;
256	        }
257	        owner.setTelephone(telephone);
258	        if (owner.getEmail() != null) {
259	            owner.setEmail(owner.getEmail().toLowerCase());
260	        }
261	        if (!owner.postcodeValidForLocality()) {
262	            return false;
263	        }
264	        if (owner.getRegistrationDate() == null) {
265	            owner.setRegistrationDate(LocalDate.now());
266	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
267	            return false;
268	        }
269	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
270	        return true;
271	    }
272	
273	    /**
274	     * Roll the given date forward to the next business day when it falls on a
275	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
276	     * weekday is returned unchanged. Applied to the effective registration date
277	     * (whether supplied in the request or defaulted to the server date) so that
278	     * every value derived from it uses the adjusted business day.
279	     *
280	     * @param date the effective registration date
281	     * @return the same date if it is a weekday, otherwise the next Monday
282	     */
283	    private static LocalDate rollToBusinessDay(LocalDate date) {
284	        switch (date.getDayOfWeek()) {
285	            case SATURDAY:
286	                return date.plusDays(2);
287	            case SUNDAY:
288	                return date.plusDays(1);
289	            default:
290	                return date;
291	        }
292	    }
293	
294	    /**
295	     * Determine whether the candidate owner's identity key collides with any existing
296	     * owner's. This is the single, consolidated duplicate check: it subsumes the
297	     * former separate telephone, email and household checks by comparing the whole
298	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
299	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
300	     * that agree on some — but not all — of the key's parts (for example two members of
301	     * the same household with different telephones) are not duplicates. Evaluated after
302	     * normalisation and household resolution, so the candidate's key reflects its
303	     * canonical field values and any household it has joined.
304	     *
305	     * @param owner the candidate owner being created, after household resolution
306	     * @return {@code true} if an existing owner has the same identity key
307	     */
308	    private boolean identityKeyAlreadyUsed(Owner owner) {
309	        String identityKey = owner.getIdentityKey();
310	        return this.clinicService.findAllOwners().stream()
311	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
312	    }
313	
314	    /**
315	     * Find an existing owner that belongs to the same household as the given owner,
316	     * i.e. shares the same last name and address (compared case-insensitively with
317	     * runs of whitespace collapsed to a single space).
318	     *
319	     * @param owner the candidate owner being created
320	     * @return the matching existing owner, or empty if none exists
321	     */
322	    private Optional<Owner> findHouseholdMember(Owner owner) {
323	        return this.clinicService.findAllOwners().stream()
324	            .filter(existing -> existing.sameHouseholdAs(owner))
325	            .findFirst();
326	    }
327	
328	    /**
329	     * Assign the joining owner and an existing household member the same stable
330	     * household identifier. The identifier is derived deterministically from the
331	     * shared household key (last name + address, normalised), so every owner in a
332	     * household resolves to the same value; the existing member is updated when it
333	     * does not already carry it.
334	     *
335	     * @param owner    the owner being created
336	     * @param existing an existing owner in the same household
337	     */
338	    private void joinHousehold(Owner owner, Owner existing) {
339	        String householdId = owner.computeHouseholdId();
340	        owner.setHouseholdId(householdId);
341	        if (!householdId.equals(existing.getHouseholdId())) {
342	            existing.setHouseholdId(householdId);
343	            this.clinicService.saveOwner(existing);
344	        }
345	    }
346	
347	    /**
348	     * Assign the owner's computed-at-creation attributes in place: its customer code,
349	     * namesake count, membership number, bulk-signup warning and household size. Unlike
350	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
351	     * derived once here — from the owner's own (already normalised) fields and from the
352	     * wider owner population — and persisted with the owner. Run after normalisation,
353	     * household resolution and the identity-key check, so every value reflects the
354	     * owner's final field values and any household it has joined, and immediately before
355	     * the owner is saved.
356	     *
357	     * <p>Ordering matters: the customer code is assigned first because the membership
358	     * number is built from it.
359	     *
360	     * @param owner the candidate owner being created, after household resolution
361	     */
362	    private void assignDerivedAttributes(Owner owner) {
363	        owner.setCustomerCode(owner.computeCustomerCode());
364	        owner.setNamesakeCount(countNamesakes(owner));
365	        owner.setMembershipNumber(membershipNumber(owner));
366	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
367	        owner.setHouseholdSize(householdSize(owner));
368	        assignPossibleDuplicate(owner);
369	    }
370	
371	    /**
372	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
373	     * match — distinct from the hard {@code identityKey} duplicate already rejected with
374	     * 409 — is an existing owner that shares this owner's last name (compared
375	     * case-insensitively) and postcode but carries a different (normalised) telephone.
376	     * When such a match exists the owner is still created, but with
377	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
378	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
379	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
380	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
381	     * are considered.
382	     *
383	     * @param owner the candidate owner being created, after household resolution
384	     */
385	    private void assignPossibleDuplicate(Owner owner) {
386	        String lastName = normalizeName(owner.getLastName());
387	        String postcode = owner.getPostcode();
388	        String telephone = owner.getTelephone();
389	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
390	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
391	                && normalizeName(existing.getLastName()).equals(lastName)
392	                && telephone != null && !telephone.equals(existing.getTelephone()))
393	            .min(Comparator.comparing(Owner::getId));
394	        if (match.isPresent()) {
395	            owner.setPossibleDuplicate(true);
396	            owner.setPossibleDuplicateOf(match.get().getId());
397	        } else {
398	            owner.setPossibleDuplicate(false);
399	            owner.setPossibleDuplicateOf(null);
400	        }
401	    }
402	
403	    /**
404	     * Count how many owners belong to the given owner's household once this create
405	     * completes: the owners that already share its {@code householdId} plus the owner
406	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
407	     * so the household identifier (and any existing member updated to it) is already in
408	     * place. An owner that has not joined a household (no {@code householdId}) is a
409	     * household of one.
410	     *
411	     * @param owner the candidate owner being created, after household resolution
412	     * @return the household member count after this create (at least {@code 1})
413	     */
414	    private int householdSize(Owner owner) {
415	        String householdId = owner.getHouseholdId();
416	        if (householdId == null) {
417	            return 1;
418	        }
419	        long existing = this.clinicService.findAllOwners().stream()
420	            .filter(other -> householdId.equals(other.getHouseholdId()))
421	            .count();
422	        return (int) existing + 1;
423	    }
424	
425	    /**
426	     * Count the existing owners that share the given owner's first and last name,
427	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
428	     * before the new owner is saved, so the result reflects only owners that
429	     * already existed at creation time.
430	     *
431	     * @param owner the candidate owner being created
432	     * @return the number of existing namesakes
433	     */
434	    private int countNamesakes(Owner owner) {
435	        String firstName = normalizeName(owner.getFirstName());
436	        String lastName = normalizeName(owner.getLastName());
437	        return (int) this.clinicService.findAllOwners().stream()
438	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
439	                && normalizeName(existing.getLastName()).equals(lastName))
440	            .count();
441	    }
442	
443	    private static String normalizeName(String value) {
444	        return value == null ? "" : value.trim().toLowerCase();
445	    }
446	
447	    /**
448	     * Determine whether the given city has already reached its owner capacity, i.e.
449	     * it already contains 50 or more existing owners (compared case-insensitively
450	     * with surrounding whitespace trimmed). A new owner may not be created in a city
451	     * that is at capacity.
452	     *
453	     * @param city the candidate owner's city
454	     * @return {@code true} if the city already holds 50 or more owners
455	     */
456	    private boolean cityIsAtCapacity(String city) {
457	        String normalizedCity = normalizeName(city);
458	        long count = this.clinicService.findAllOwners().stream()
459	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
460	            .count();
461	        return count >= 50;
462	    }
463	
464	    /**
465	     * Determine whether the daily owner-creation limit has already been reached, i.e.
466	     * 100 or more owners already carry the given registration date. A new owner may
467	     * not be created once that day's cap is reached.
468	     *
469	     * @param registrationDate the registration date the new owner would be created with
470	     * @return {@code true} if 100 or more existing owners share that registration date
471	     */
472	    private boolean dailyLimitReached(LocalDate registrationDate) {
473	        long count = this.clinicService.findAllOwners().stream()
474	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
475	            .count();
476	        return count >= 100;
477	    }
478	
479	    /**
480	     * Determine whether more than 80 owners have already been created for the given
481	     * registration date, i.e. strictly more than 80 existing owners carry that date.
482	     * Evaluated before the new owner is saved, so it reflects only owners that
483	     * already existed at creation time.
484	     *
485	     * @param registrationDate the registration date the new owner would be created with
486	     * @return {@code true} if more than 80 existing owners share that registration date
487	     */
488	    private boolean bulkSignupWarning(LocalDate registrationDate) {
489	        long count = this.clinicService.findAllOwners().stream()
490	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
491	            .count();
492	        return count > 80;
493	    }
494	
495	    /**
496	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
497	     * one place so it stays in step with the owner's identity: it reports the assigned
498	     * customer code alongside the owner's id, registration date and membership level.
499	     *
500	     * @param owner the owner that has just been created and saved
501	     */
502	    private void auditOwnerCreated(Owner owner) {
503	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
504	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
505	    }
506	
507	    /**
508	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
509	     * where {@code <customerCode>} is the owner's already-assigned customer code and
510	     * YY is the last two digits of the registration date's year (e.g.
511	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
512	     * have been set.
513	     *
514	     * @param owner the owner being created, with customer code and registration date
515	     *              already assigned
516	     * @return the assigned membership number
517	     */
518	    private String membershipNumber(Owner owner) {
519	        int yy = owner.getRegistrationDate().getYear() % 100;
520	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
521	    }
522	
523	    /**
524	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
525	     * code when present, otherwise assume country code '+61' and drop a single
526	     * leading '0' from the national digits. Spaces, dashes and brackets are
527	     * stripped. The result must contain 8 to 15 digits after the '+'.
528	     *
529	     * <p>In addition, the national-number length is validated against the country
530	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
531	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
532	     * whose national-number length is wrong for its country code is rejected.
533	     *
534	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
535	     *         input cannot form a valid E.164 number.
536	     */
537	    private static String toE164(String raw) {
538	        if (raw == null) {
539	            return null;
540	        }
541	        String cleaned = raw.replaceAll("[\\s()-]", "");
542	        String digits;
543	        if (cleaned.startsWith("+")) {
544	            digits = cleaned.substring(1);
545	        } else {
546	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
547	            digits = "61" + national;
548	        }
549	        if (!digits.matches("\\d{8,15}")) {
550	            return null;
551	        }
552	        if (!nationalNumberLengthValid(digits)) {
553	            return null;
554	        }
555	        return "+" + digits;
556	    }
557	
558	    /**
559	     * Validate the length of the national number (the digits after the country
560	     * code) against the country code carried by the given E.164 digit string: a
561	     * {@code 61} (Australia) number requires exactly 9 national digits and a
562	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
563	     * without a pinned length are accepted (only the generic 8-15 digit rule
564	     * applies to them).
565	     *
566	     * @param digits the E.164 digits without the leading '+'
567	     * @return {@code true} if the national-number length is correct for the country
568	     */
569	    private static boolean nationalNumberLengthValid(String digits) {
570	        if (digits.startsWith("61")) {
571	            return digits.length() - 2 == 9;
572	        }
573	        if (digits.startsWith("1")) {
574	            return digits.length() - 1 == 10;
575	        }
576	        return true;
577	    }
578	}
